Sentry.init({
  app,
  dsn: dsnFromRuntimeConfig,
  release: import.meta.env.VITE_COMMIT_SHA,
  environment: "production",
  tracesSampleRate: 0.15,
  replaysOnErrorSampleRate: 1,
  beforeSend(event) {
    if (event.tags?.http_status === "401") return null
    return scrubPii(event)
  },
})

